<?php
require_once dirname(__DIR__).'/includes/features.php';admin_require();$errors=[];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{admin_csrf();$calendarDb=db();$id=filter_var($_POST['id']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
  if(($_POST['action']??'')==='publish'){publish_slot(db(),input_text($_POST,'starts_at',16));}
  elseif(($_POST['action']??'')==='block'&&$id){db()->prepare("UPDATE consultation_slots SET status='blocked' WHERE id=? AND status='available'")->execute([$id]);}
  elseif(($_POST['action']??'')==='reopen'&&$id){$q=db()->prepare("UPDATE consultation_slots SET status='available' WHERE id=? AND status='blocked' AND starts_at>? AND NOT EXISTS (SELECT 1 FROM consultation_bookings WHERE slot_id=?)");$q->execute([$id,gmdate('Y-m-d H:i:s',time()+3600),$id]);if($q->rowCount()!==1)throw new InvalidArgumentException('Only a future, unbooked blocked slot can be reopened.');}
  elseif(($_POST['action']??'')==='cancel'&&$id){
   db()->beginTransaction();db()->prepare("UPDATE consultation_bookings SET status='cancelled' WHERE slot_id=? AND status='confirmed'")->execute([$id]);db()->prepare("UPDATE consultation_slots SET status='blocked' WHERE id=? AND status='booked'")->execute([$id]);db()->commit();
  }else throw new InvalidArgumentException('Invalid calendar action.');
  redirect('admin/calendar.php');
 }catch(Throwable $e){if(isset($calendarDb)&&$calendarDb->inTransaction())$calendarDb->rollBack();$errors['_form']=$e instanceof InvalidArgumentException?$e->getMessage():'Could not update availability. Check the database migration; duplicate times cannot be published.';}
}
try{$q=db()->prepare('SELECT s.*,b.id AS booking_id,b.name,b.email,b.status AS booking_status FROM consultation_slots s LEFT JOIN consultation_bookings b ON b.slot_id=s.id WHERE s.starts_at>? ORDER BY s.starts_at LIMIT 300');$q->execute([gmdate('Y-m-d H:i:s',time()-7*86400)]);$slots=$q->fetchAll();}catch(Throwable $e){$slots=[];$errors['_form']='Calendar storage is unavailable. Import database/features.sql and configure the database.';}
page_start('admin',''); ?>
<section class="section"><div class="container"><h1>Consultation calendar</h1><?php admin_navigation();errors_summary($errors); ?><div class="grid-2"><form class="form-card" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="publish"><h2>Publish a 30-minute slot</h2><p class="note">Only publish times you can attend. Times are entered in <?= e(config('timezone')) ?>. Starts must be on the hour or half hour and at least one hour ahead.</p><?php field('starts_at','Start time','datetime-local',[],[],true,[],'step="1800"'); ?><button class="button">Publish availability</button></form><div><h2>Availability rules</h2><p>A published slot can be booked once. Blocking removes an unbooked slot from public availability.</p><p>Cancellation keeps the time blocked and retains the booking record. Contact the visitor separately to explain a cancellation; this action does not send an email.</p><p class="note">This is Semraa’s internal calendar. There is no Google/Outlook calendar sync.</p></div></div><div class="table-wrap"><table><thead><tr><th>Time (<?= e(config('timezone')) ?>)</th><th>Status</th><th>Booking</th><th>Action</th></tr></thead><tbody><?php foreach($slots as $slot): ?><tr><td><?= e(slot_label($slot['starts_at'])) ?></td><td><?= e($slot['status']) ?></td><td><?php if($slot['booking_id']): ?>CONSULT-<?= (int)$slot['booking_id'] ?><br><?= e($slot['name']) ?><br><?= e($slot['email']) ?><br><?= e($slot['booking_status']) ?><?php endif; ?></td><td><?php if(in_array($slot['status'],['available','booked'],true)||($slot['status']==='blocked'&&!$slot['booking_id'])): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$slot['id'] ?>"><input type="hidden" name="action" value="<?= $slot['status']==='booked'?'cancel':($slot['status']==='blocked'?'reopen':'block') ?>"><button class="button button-outline button-small"><?= $slot['status']==='booked'?'Cancel booking and block':($slot['status']==='blocked'?'Reopen slot':'Block this slot') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$slots&&!$errors): ?><p>No times published yet.</p><?php endif; ?></div></section><?php page_end(); ?>
